const dictionaries = {
  "zh-CN": zhCN,
  "en-US": enUS,
} satisfies Record<Locale, typeof zhCN>;

export type Dictionary = typeof zhCN;

export function getConfirmationInformationLibraryMatchCopy(locale: string) {
  return dictionaries[locale.toLowerCase().startsWith("zh") ? "zh-CN" : "en-US"]
    .confirmations.informationLibraryMatch;
}

